-- ===== supabase/updates/20261204005900_nexamon_condition_values.sql =====
-- ===== idempotent copy of migrations/20261204005900_nexamon_condition_values.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- Nexamon (ADR-165): the condition weighs more on a raw copy's value: poor 70 %, good 90 %, near mint and mint 100 %.
-- The factors live in game_config (nexamon.conditions.valueBps); a slab still counts by its grade only.
create or replace function public.nexamon_copy_factor_bps(p_condition text, p_grade integer)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  cfg jsonb := public.nexamon_cfg();
begin
  if p_grade >= 11 then
    return coalesce((cfg #>> '{grading,blackLabel,valueBps}')::integer, 100000);
  end if;
  if p_grade is not null then
    return coalesce((cfg #>> array['grading', 'valueBps', (least(greatest(p_grade, 1), 10) - 1)::text])::integer, 10000);
  end if;
  return coalesce((cfg #>> array['conditions', 'valueBps', p_condition])::integer, 10000);
end;
$$;

-- ===== supabase/updates/20261204005960_nexamon_graded_quiet.sql =====
-- ===== idempotent copy of migrations/20261204005960_nexamon_graded_quiet.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 5960 · Nexamon: the ASP notification does not spoil the grade (ADR-165)
-- =============================================================================
-- Owner's wish: a card back from ASP comes as a sealed package that the player opens; the notification (in-app and
-- push) only says the package is waiting. Neither title, text nor payload carries the grade. The Black Label feed
-- item (friends' feed, gossip for NEXA Nachrichten) is no longer posted when the grading finishes: the server does
-- not know when the owner opens the package (that happens on the device), so it would come before the reveal.
-- Mission events stay as they were. Replaces nexamon_finish_gradings() of 5850 entirely (create or replace).
-- Idempotent: runs unchanged as supabase/updates/20261204005960_nexamon_graded_quiet.sql.

create or replace function public.nexamon_finish_gradings(p_player uuid default null, p_now timestamptz default null)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now   timestamptz := coalesce(p_now, public.game_now());
  v_n     integer := 0;
  v_grade integer;
  r       record;
begin
  for r in select c.id, c.owner_id, c.card_key, c.condition, c.serial from public.nexamon_copies c
            where c.grading_until is not null and c.grading_until <= v_now
              and (p_player is null or c.owner_id = p_player)
            order by c.grading_until, c.id limit 200
            for update skip locked loop
    v_grade := public.nexamon_roll_grade(r.condition, random());
    update public.nexamon_copies set grade = v_grade, graded_at = v_now, grading_until = null where id = r.id;
    if r.owner_id is not null then
      -- the grade stays a surprise: only the waiting package is announced
      perform public.social_notify(r.owner_id, 'nexamon_graded', 'Paket von ASP',
        'Deine Nexamon-Karte ist zurück von ASP. Das versiegelte Paket wartet darauf, dass du es öffnest.',
        jsonb_build_object('copy_id', r.id, 'card_key', r.card_key, 'serial', r.serial),
        '/nexamon', 'nexamon_graded:' || r.id::text || ':' || extract(epoch from v_now)::bigint::text);
      perform public.mission_event(r.owner_id, 'nexamon_graded', 1, null);
      if v_grade >= 10 then
        perform public.mission_event(r.owner_id, 'nexamon_ten', 1, null);
      end if;
      if v_grade >= 11 then
        perform public.mission_event(r.owner_id, 'nexamon_black_label', 1, null);
      end if;
    end if;
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;
comment on function public.nexamon_finish_gradings(uuid, timestamptz) is
  'Finishes due ASP gradings (ADR-165): rolls the grade, notifies the owner without the grade (sealed package), '
  'mission events. No feed item (the reveal happens on the device).';

-- ===== supabase/updates/20261204006100_stock_pump.sql =====
-- ===== idempotent copy of migrations/20261204006100_stock_pump.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 6100 · No money from pumping the own stock (ADR-170)
-- =============================================================================
-- The loop: a founder takes cash out of the company, buys the own stock (the price rises by the player impact),
-- then lets the company issue new shares (capital increase). AI investors subscribed their usual 60 to 100 % at
-- 90 % of the pushed market price (at least 1 EUR) and paid it into the company cash, which the founder withdrew
-- again. Each round printed money from the financial market; with a stock at 0.45 EUR a 25 % increase brought
-- 250.000 EUR. The fix:
-- 1. AI investors pay at most the fair value: in a capital increase they take their share
--    only while the price is at most aiMaxPremiumBps (100 %) of the fair value, fair = (company value + new money)
--    / shares after the increase (company_share_offers.ai_factor 1 or 0, set when the offer starts).
-- 2. A capital increase at most once per capitalIncreaseCooldownHours (capital_increase_cooldown, NX221).
-- 3. Issue proceeds (IPO, capital increase) cannot be withdrawn for issueProceedsLockHours
--    (issue_proceeds_locked, NX222).
-- 4. Insider rule: a founder cannot buy the own stock for insiderCooldownHours after money went from the company
--    to him (withdrawal, payout, dividend) (insider_cooldown, NX220).
-- 5. Player stocks move at most dailyBandBps around the previous close per day; the founder's own shares no
--    longer lift the value funds' anchor (holdings premium).
-- Idempotent: runs unchanged as supabase/updates/20261204006100_stock_pump.sql.

-- ---------------------------------------------------------------------------
-- A. Error keys
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.api_error(text)'::regprocedure);
  v_a   text := $q$    else 'NX007'
$q$;
begin
  if position('''insider_cooldown''' in v_def) = 0 then
    if position(v_a in v_def) = 0 then
      raise exception 'api_error() has an unexpected shape; add insider_cooldown (NX220 to NX222) by hand';
    end if;
    execute replace(v_def, v_a, $q$    when 'insider_cooldown'           then 'NX220'
    when 'capital_increase_cooldown'  then 'NX221'
    when 'issue_proceeds_locked'      then 'NX222'
$q$ || v_a);
  end if;
end;
$do$;

-- ---------------------------------------------------------------------------
-- B. Helpers
-- ---------------------------------------------------------------------------
alter table public.company_share_offers add column if not exists ai_factor double precision not null default 1;
comment on column public.company_share_offers.ai_factor is
  'ADR-170: share of their usual part AI investors subscribe (issue_ai_factor at the start of a capital increase; 1 for IPOs).';

-- issueAiFactor (src/lib/sim/startup.ts): AI investors pay at most the fair value
create or replace function public.issue_ai_factor(p_fair_cents double precision, p_price_cents double precision)
returns double precision
language sql
stable
security definer
set search_path = ''
as $$
  select case
           when coalesce(p_fair_cents, 0) <= 0 or coalesce(p_price_cents, 0) <= 0 then 0
           when p_price_cents * 10000 > p_fair_cents * public.config_double('startups', '{ipo,aiMaxPremiumBps}', 10000) then 0
           else 1
         end;
$$;

-- Issue proceeds (IPO, capital increase) of the last issueProceedsLockHours in the company cash
create or replace function public.listed_issue_locked_cents(p_company uuid)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(sum(e.amount_cents), 0)::bigint
    from public.ledger_accounts ca
    join public.ledger_entries e on e.account_id = ca.id and e.amount_cents > 0
    join public.ledger_transactions t on t.id = e.transaction_id and t.ref_type = 'share_offer'
   where ca.owner_company_id = p_company and ca.kind = 'company_cash'
     and e.created_at > now() - public.config_double('startups', '{ipo,issueProceedsLockHours}', 72) * interval '1 hour';
$$;

-- Insider rule: money went from the founder's company to him within insiderCooldownHours
create or replace function public.player_stock_insider_blocked(p_player uuid, p_security uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
      from public.companies c
      join public.player_companies pc on pc.company_id = c.id and pc.founder_id = p_player
      join public.ledger_accounts ca on ca.owner_company_id = c.id and ca.kind = 'company_cash'
      join public.ledger_entries e1 on e1.account_id = ca.id and e1.amount_cents < 0
       and e1.created_at > now() - public.config_double('trading', '{playerStocks,insiderCooldownHours}', 24) * interval '1 hour'
      join public.ledger_entries e2 on e2.transaction_id = e1.transaction_id and e2.amount_cents > 0
      join public.ledger_accounts pa on pa.id = e2.account_id and pa.owner_player_id = p_player and pa.kind = 'player_cash'
     where c.security_id = p_security);
$$;

revoke all on function public.issue_ai_factor(double precision, double precision) from public, anon, authenticated;
revoke all on function public.listed_issue_locked_cents(uuid) from public, anon, authenticated;
revoke all on function public.player_stock_insider_blocked(uuid, uuid) from public, anon, authenticated;
grant execute on function public.issue_ai_factor(double precision, double precision) to service_role;
grant execute on function public.listed_issue_locked_cents(uuid) to service_role;
grant execute on function public.player_stock_insider_blocked(uuid, uuid) to service_role;

-- ---------------------------------------------------------------------------
-- C. place_order: the insider rule
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.place_order(uuid, text, text, text, bigint, bigint, bigint)'::regprocedure);
  v_a   text := $t$  if s.kind = 'bond' and v_level < public.unlock_level('bonds') then
    perform public.api_error('locked');
  end if;
$t$;
begin
  if position('player_stock_insider_blocked' in v_def) > 0 then
    return;
  end if;
  if position(v_a in v_def) = 0 then
    raise exception 'place_order() has an unexpected shape; add the insider rule (ADR-170) by hand';
  end if;
  execute replace(v_def, v_a, v_a || $t$  -- ADR-170: no buying the own stock with money just taken out of the company
  if v_side = 'buy' and s.kind = 'stock' and public.player_stock_insider_blocked(v_player, s.id) then
    perform public.api_error('insider_cooldown');
  end if;
$t$);
end;
$do$;

-- ---------------------------------------------------------------------------
-- D. capital_increase: cooldown and the AI factor
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.capital_increase(uuid, integer)'::regprocedure);
  v_a   text := $t$  v_new := c.shares_outstanding * 1000000 * p_share_percent / 100;
$t$;
  v_b   text := $t$  perform public.company_system_message(v_company, 'Kapitalerhöhung: neue Aktien zu '$t$;
begin
  if position('capital_increase_cooldown' in v_def) > 0 then
    return;
  end if;
  if position(v_a in v_def) = 0 or position(v_b in v_def) = 0 then
    raise exception 'capital_increase() has an unexpected shape; add the cooldown and the AI factor (ADR-170) by hand';
  end if;
  v_def := replace(v_def, v_a, v_a || $t$  -- ADR-170: at most once per capitalIncreaseCooldownHours
  if exists (select 1 from public.company_share_offers o
              where o.company_id = v_company and o.kind = 'capital_increase'
                and o.created_at > now() - public.cfg_num(v_ipo, '{capitalIncreaseCooldownHours}', 24) * interval '1 hour') then
    perform public.api_error('capital_increase_cooldown');
  end if;
$t$);
  v_def := replace(v_def, v_b, $t$  -- ADR-170: AI investors pay at most the fair value after the increase
  update public.company_share_offers o
     set ai_factor = public.issue_ai_factor(
           (public.company_value_cents(v_company) * public.listed_price_factor(v_company) + v_new / 1000000.0 * v_price)
             / greatest(1, c.shares_outstanding + v_new / 1000000.0),
           v_price)
   where o.company_id = v_company and o.request_id = p_request_id and o.kind = 'capital_increase';
$t$ || v_b);
  execute v_def;
end;
$do$;

-- share_offer_ai_topup: the AI part times ai_factor
do $do$
declare
  v_def text := pg_get_functiondef('public.share_offer_ai_topup(uuid, timestamp with time zone, boolean)'::regprocedure);
  v_a   text := $t$  v_target := floor(o.shares_offered_e6
$t$;
begin
  if position('o.ai_factor' in v_def) > 0 then
    return;
  end if;
  if position(v_a in v_def) = 0 then
    raise exception 'share_offer_ai_topup() has an unexpected shape; add the AI factor (ADR-170) by hand';
  end if;
  execute replace(v_def, v_a, $t$  v_target := floor(o.shares_offered_e6 * greatest(0, least(1, o.ai_factor))
$t$);
end;
$do$;

-- ---------------------------------------------------------------------------
-- E. listed_withdraw_check: issue proceeds stay in the company for a while
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.listed_withdraw_check(uuid, bigint)'::regprocedure);
  v_a   text := $t$  if public.listed_reserved_cents(p_company) > 0 then
$t$;
begin
  if position('issue_proceeds_locked' in v_def) > 0 then
    return;
  end if;
  if position(v_a in v_def) = 0 then
    raise exception 'listed_withdraw_check() has an unexpected shape; add the issue lock (ADR-170) by hand';
  end if;
  execute replace(v_def, v_a, $t$  -- ADR-170: money raised from investors is not the founder's
  if public.listed_issue_locked_cents(p_company) > 0
     and public.listed_free_cash(p_company) - public.listed_issue_locked_cents(p_company) < p_amount_cents then
    perform public.api_error('issue_proceeds_locked');
  end if;
$t$ || v_a);
end;
$do$;

-- ---------------------------------------------------------------------------
-- F. market_tick_at: daily band for player stocks, no premium from the founder's own shares
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.market_tick_at(timestamp with time zone)'::regprocedure);
  v_d   text := $t$  c_bondvol   double precision;
$t$;
  v_c   text := $t$  c_bondvol   := public.cfg_num(v_bonds, '{volatilityMultiplier}', 3);
$t$;
  v_s   text := $t$           q.last_price_e4,
$t$;
  v_h   text := $t$      v_held := greatest(0, r.held_e6 / 1000000.0 * v_price / 100.0);
$t$;
  v_n   text := $t$      v_new := greatest(c_minprice, v_new);
      v_mm  := v_mm * (1 - c_mm_speed);
$t$;
begin
  if position('band_founder' in v_def) > 0 then
    return;
  end if;
  if position(v_d in v_def) = 0 or position(v_c in v_def) = 0 or position(v_s in v_def) = 0
     or position(v_h in v_def) = 0 or position(v_n in v_def) = 0 then
    raise exception 'market_tick_at() has an unexpected shape; add the player stock band (ADR-170) by hand';
  end if;
  v_def := replace(v_def, v_d, v_d || $t$  c_band      double precision;
  v_bref      double precision;
$t$);
  v_def := replace(v_def, v_c, v_c || $t$  c_band      := greatest(0, public.cfg_num(v_trading, '{playerStocks,dailyBandBps}', 0)) / 10000.0;
$t$);
  v_def := replace(v_def, v_s, $t$           q.last_price_e4, q.prev_close_e4 as band_prev_e4,
           (select pcx.founder_id from public.player_companies pcx where pcx.company_id = s.company_id) as band_founder,
           coalesce((select sum(px.quantity_e6) from public.positions px
                       join public.player_companies pcy on pcy.company_id = s.company_id and pcy.founder_id = px.player_id
                      where px.security_id = s.id and px.status = 'open' and px.side = 'long'), 0) as founder_e6,
$t$);
  v_def := replace(v_def, v_h, $t$      v_held := greatest(0, (r.held_e6 - r.founder_e6) / 1000000.0 * v_price / 100.0);
$t$);
  v_def := replace(v_def, v_n, $t$      v_new := greatest(c_minprice, v_new);
      -- ADR-170: a player stock stays within dailyBandBps of the previous close
      if r.band_founder is not null and c_band > 0 then
        v_bref := case when v_new_day then r.last_price_e4 else coalesce(r.band_prev_e4, r.last_price_e4) end;
        v_new := greatest(c_minprice, least(ceil(v_bref * (1 + c_band))::bigint,
                                            greatest(floor(v_bref / (1 + c_band))::bigint, v_new)));
      end if;
      v_mm  := v_mm * (1 - c_mm_speed);
$t$);
  execute v_def;
end;
$do$;

-- ===== supabase/updates/20261204006110_nft_cadence.sql =====
-- ===== idempotent copy of migrations/20261204006110_nft_cadence.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 6110 · NFT collectors are busy all day (ADR-170)
-- =============================================================================
-- Why the collectors seemed to act once a day: their offers stayed open 24 hours and at most maxOpenAiOffers (3)
-- collectors bid on one NFT, so an NFT got its three offers in the first minutes and then nothing until the next day;
-- their trades among themselves stopped at the day cap (300) by the afternoon, purchases at 60 a day; nobody bid in
-- player auctions. Now:
-- 1. A collector's offer runs out after nfts.ai.offerHours (2), so new offers come all day.
-- 2. Hourly caps: maxBuysPerHour (6) purchases from players, trade.perHour (24) trades among collectors; day caps
--    100 and 480. Purchases and auction bids together stay within ai.budgetCentsPerDay (300.000 EUR).
-- 3. Collectors bid in auctions (artwork_auctions.leader_ai, artwork_bids.bidder_ai): per minute and auction with
--    ai.auction.bidChanceBps, the minimum bid, only while it is at most their valuation. The money comes from the
--    households into art_escrow; an outbid collector gets it back to the households. A won auction makes the NFT a
--    collector's (they offer it again at their markup).
-- Idempotent: runs unchanged as supabase/updates/20261204006110_nft_cadence.sql.

-- ---------------------------------------------------------------------------
-- A. Schema: collectors as bidders
-- ---------------------------------------------------------------------------
alter table public.artwork_auctions add column if not exists leader_ai text;
alter table public.artwork_bids add column if not exists bidder_ai text;
alter table public.artwork_bids alter column bidder_id drop not null;
do $do$
begin
  if not exists (select 1 from pg_constraint where conname = 'artwork_bids_bidder_check') then
    alter table public.artwork_bids add constraint artwork_bids_bidder_check
      check ((bidder_id is null) <> (bidder_ai is null) and (bidder_ai is null or char_length(bidder_ai) between 1 and 40));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'artwork_auctions_leader_check') then
    alter table public.artwork_auctions add constraint artwork_auctions_leader_check
      check (leader_id is null or leader_ai is null);
  end if;
end;
$do$;
comment on column public.artwork_auctions.leader_ai is 'ADR-170: an AI collector leads (leader_id is null then); money in art_escrow from the households.';
comment on column public.artwork_bids.bidder_ai is 'ADR-170: bid of an AI collector (bidder_id null).';

-- ---------------------------------------------------------------------------
-- B. Collectors bid in auctions
-- ---------------------------------------------------------------------------
-- What the collectors paid players today plus what they hold in player auctions
create or replace function public.nft_ai_spent_today(p_now timestamptz)
returns bigint
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce((select sum(s.price_cents) from public.artwork_sales s
                    where s.buyer_ai is not null and s.seller_ai is null and s.seller_id is not null
                      and s.at >= ((p_now at time zone 'Europe/Berlin')::date)::timestamp at time zone 'Europe/Berlin'), 0)
       + coalesce((select sum(au.current_cents) from public.artwork_auctions au
                    where au.status = 'open' and au.leader_ai is not null and au.seller_id is not null), 0);
$$;

create or replace function public.nft_ai_bid_auctions(p_now timestamptz)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  ai       jsonb := public.nfts_cfg() -> 'ai';
  v_escrow uuid := public.ledger_system_account('art_escrow');
  v_house  uuid := public.ledger_system_account('households');
  v_window double precision := public.config_double('artworks', '{auction,antiSnipeMinutes}', 2) * 60;
  au       public.artwork_auctions;
  r        record;
  a        public.artworks;
  v_n      integer := 0;
  v_min    bigint;
  v_value  bigint;
  v_name   text;
  v_cash   bigint;
  v_bid    bigint;
  v_entries jsonb;
begin
  if ai is null or ai -> 'auction' is null then
    return 0;
  end if;
  for r in select x.id from public.artwork_auctions x
            where x.status = 'open' and x.ends_at > p_now order by x.ends_at, x.id limit 50 loop
    exit when v_n >= coalesce((ai #>> '{auction,maxBidsPerRun}')::integer, 0);
    continue when random() * 10000 >= coalesce((ai #>> '{auction,bidChanceBps}')::integer, 0);
    select * into au from public.artwork_auctions where id = r.id for update skip locked;
    continue when au.id is null or au.status <> 'open' or au.ends_at <= p_now;
    v_min := public.artwork_min_bid_cents(au.start_cents, au.current_cents);
    v_value := public.nft_ai_value_cents(au.artwork_id, p_now);
    -- never above the valuation; player auctions within the daily budget
    continue when v_min > v_value;
    continue when au.seller_id is not null
              and public.nft_ai_spent_today(p_now) - case when au.leader_ai is not null then coalesce(au.current_cents, 0) else 0 end
                  + v_min > coalesce((ai ->> 'budgetCentsPerDay')::bigint, 0);
    select x.balance_cents into v_cash from public.ledger_accounts x where x.id = v_house;
    continue when coalesce(v_cash, 0) < v_min;
    select c into v_name from jsonb_array_elements_text(ai -> 'collectors') c
     where c is distinct from au.leader_ai order by random() limit 1;
    continue when v_name is null;
    select * into a from public.artworks where id = au.artwork_id;

    insert into public.artwork_bids (auction_id, bidder_id, bidder_ai, amount_cents, at)
    values (au.id, null, v_name, v_min, p_now) returning id into v_bid;
    v_entries := jsonb_build_array(jsonb_build_object('account_id', v_house, 'amount_cents', -v_min),
                                   jsonb_build_object('account_id', v_escrow, 'amount_cents', v_min));
    if au.current_cents is not null and au.leader_id is not null then
      v_entries := v_entries
        || jsonb_build_object('account_id', v_escrow, 'amount_cents', -au.current_cents)
        || jsonb_build_object('account_id', public.ledger_player_account(au.leader_id, 'player_cash'), 'amount_cents', au.current_cents);
    elsif au.current_cents is not null and au.leader_ai is not null then
      v_entries := v_entries
        || jsonb_build_object('account_id', v_escrow, 'amount_cents', -au.current_cents)
        || jsonb_build_object('account_id', v_house, 'amount_cents', au.current_cents);
    end if;
    perform public.ledger_post('artwork_bid', v_entries, 'Gebot eines KI-Sammlers', 'artwork_auction', au.id,
                               'art:aibid:' || v_bid::text, null,
                               jsonb_build_object('amount_cents', v_min, 'collector', v_name,
                                                  'refunded_player', au.leader_id, 'refunded_cents', au.current_cents));
    update public.artwork_auctions
       set leader_id = null, leader_ai = v_name, current_cents = v_min, bids = bids + 1,
           ends_at = case when extract(epoch from (au.ends_at - p_now)) < v_window
                          then p_now + make_interval(secs => v_window) else au.ends_at end
     where id = au.id;
    if au.leader_id is not null then
      perform public.social_notify(au.leader_id, 'art_outbid', v_name || ' hat dich überboten',
        '„' || a.title || '“ (' || public.artwork_code(a.serial) || '): neues Gebot ' || public.format_eur(v_min),
        jsonb_build_object('auction_id', au.id, 'artwork_id', a.id, 'code', public.artwork_code(a.serial), 'title', a.title,
                           'amount_cents', v_min, 'nickname', v_name),
        '/artworks', 'art_outbid:' || au.id::text || ':' || (au.bids + 1)::text);
    end if;
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;
revoke all on function public.nft_ai_spent_today(timestamptz) from public, anon, authenticated;
revoke all on function public.nft_ai_bid_auctions(timestamptz) from public, anon, authenticated;
grant execute on function public.nft_ai_spent_today(timestamptz) to service_role;
grant execute on function public.nft_ai_bid_auctions(timestamptz) to service_role;

-- ---------------------------------------------------------------------------
-- C. nfts_run_due: hourly caps, budget, shorter collector offers, auction bids
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.nfts_run_due(timestamp with time zone)'::regprocedure);
  v_d   text := $t$  v_price   bigint;
$t$;
  v_b0  text := $t$  select count(*) into v_buys from public.artwork_sales s where s.buyer_ai is not null and s.seller_ai is null and s.at >= v_day;
$t$;
  v_b1  text := $t$      continue when v_buys >= (ai ->> 'maxBuysPerDay')::integer or random() * 10000 >= (ai ->> 'buyChanceBps')::integer;
$t$;
  v_b2  text := $t$      v_buys := v_buys + 1;
$t$;
  v_o   text := $t$perform public.nft_notify_offer(v_id);
$t$;
  v_t0  text := $t$   where s.seller_ai is not null and s.buyer_ai is not null and s.at >= v_day;
$t$;
  v_t1  text := $t$    exit when v_traded >= (ai #>> '{trade,perRun}')::integer or v_trades >= (ai #>> '{trade,perDay}')::integer;
$t$;
  v_t2  text := $t$    v_trades := v_trades + 1;
$t$;
  v_r   text := $t$  return jsonb_build_object('sold', v_sold,$t$;
begin
  if position('maxBuysPerHour' in v_def) > 0 then
    return;
  end if;
  if position(v_d in v_def) = 0 or position(v_b0 in v_def) = 0 or position(v_b1 in v_def) = 0
     or position(v_b2 in v_def) = 0 or position(v_o in v_def) = 0 or position(v_t0 in v_def) = 0
     or position(v_t1 in v_def) = 0 or position(v_t2 in v_def) = 0 or position(v_r in v_def) = 0 then
    raise exception 'nfts_run_due() has an unexpected shape; add the hourly caps (ADR-170) by hand';
  end if;
  v_def := replace(v_def, v_d, v_d || $t$  v_hbuys    integer;
  v_htrades  integer;
  v_spent    bigint;
$t$);
  v_def := replace(v_def, v_b0, v_b0 || $t$  -- ADR-170: hourly caps and a daily budget spread the collectors' activity over the day
  select count(*) into v_hbuys from public.artwork_sales s
   where s.buyer_ai is not null and s.seller_ai is null and s.at > v_now - interval '1 hour';
  v_spent := public.nft_ai_spent_today(v_now);
$t$);
  v_def := replace(v_def, v_b1, $t$      continue when v_buys >= (ai ->> 'maxBuysPerDay')::integer or random() * 10000 >= (ai ->> 'buyChanceBps')::integer
                    or v_hbuys >= coalesce((ai ->> 'maxBuysPerHour')::integer, 1000000)
                    or v_spent + a.ask_cents > coalesce((ai ->> 'budgetCentsPerDay')::bigint, 9000000000000000000);
$t$);
  v_def := replace(v_def, v_b2, v_b2 || $t$      v_hbuys := v_hbuys + 1;
      v_spent := v_spent + a.ask_cents;
$t$);
  v_def := replace(v_def, v_o, $t$update public.artwork_messages
       set expires_at = least(expires_at, v_now + make_interval(mins => round(coalesce((ai ->> 'offerHours')::numeric, 24) * 60)::integer))
     where id = v_id;
    perform public.nft_notify_offer(v_id);
$t$);
  v_def := replace(v_def, v_t0, v_t0 || $t$  select count(*) into v_htrades from public.artwork_sales s
   where s.seller_ai is not null and s.buyer_ai is not null and s.at > v_now - interval '1 hour';
$t$);
  v_def := replace(v_def, v_t1, $t$    exit when v_traded >= (ai #>> '{trade,perRun}')::integer or v_trades >= (ai #>> '{trade,perDay}')::integer
              or v_htrades >= coalesce((ai #>> '{trade,perHour}')::integer, 1000000);
$t$);
  v_def := replace(v_def, v_t2, v_t2 || $t$    v_htrades := v_htrades + 1;
$t$);
  v_def := replace(v_def, v_r, $t$  return jsonb_build_object('bids', public.nft_ai_bid_auctions(v_now), 'sold', v_sold,$t$);
  execute v_def;
end;
$do$;

-- ---------------------------------------------------------------------------
-- D. Auctions with a collector in the lead
-- ---------------------------------------------------------------------------
-- bid_artwork: an outbid collector's money goes back to the households
do $do$
declare
  v_def text := pg_get_functiondef('public.bid_artwork(uuid, uuid, bigint)'::regprocedure);
  v_a   text := $t$      jsonb_build_object('account_id', public.ledger_player_account(au.leader_id, 'player_cash'), 'amount_cents', au.current_cents));
  end if;
$t$;
  v_b   text := $t$     set leader_id = v_player, current_cents = p_amount_cents,$t$;
begin
  if position('leader_ai' in v_def) > 0 then
    return;
  end if;
  if position(v_a in v_def) = 0 or position(v_b in v_def) = 0 then
    raise exception 'bid_artwork() has an unexpected shape; add the collector bids (ADR-170) by hand';
  end if;
  v_def := replace(v_def, v_a, v_a || $t$  if au.leader_id is null and au.leader_ai is not null and au.current_cents is not null then
    v_entries := jsonb_build_array(
      jsonb_build_object('account_id', v_escrow, 'amount_cents', -au.current_cents),
      jsonb_build_object('account_id', public.ledger_system_account('households'), 'amount_cents', au.current_cents));
  end if;
$t$);
  v_def := replace(v_def, v_b, $t$     set leader_id = v_player, leader_ai = null, current_cents = p_amount_cents,$t$);
  execute v_def;
end;
$do$;

-- artwork_settle_auction: a collector wins (the households paid into the escrow)
do $do$
declare
  v_def text := pg_get_functiondef('public.artwork_settle_auction(uuid)'::regprocedure);
  v_a   text := $t$  if au.leader_id is null or au.current_cents is null then$t$;
  v_b   text := $t$else au.seller_id end, null, au.leader_id, null,$t$;
  v_c   text := $t$  perform public.mission_event(au.leader_id, 'art_won', 1, null);$t$;
begin
  if position('leader_ai' in v_def) > 0 then
    return;
  end if;
  if position(v_a in v_def) = 0 or position(v_b in v_def) = 0 or position(v_c in v_def) = 0 then
    raise exception 'artwork_settle_auction() has an unexpected shape; add the collector bids (ADR-170) by hand';
  end if;
  v_def := replace(v_def, v_a, $t$  if (au.leader_id is null and au.leader_ai is null) or au.current_cents is null then$t$);
  v_def := replace(v_def, v_b, $t$else au.seller_id end, null, au.leader_id, au.leader_ai,$t$);
  v_def := replace(v_def, v_c, $t$  if au.leader_id is not null then
    perform public.mission_event(au.leader_id, 'art_won', 1, null);
  end if;$t$);
  execute v_def;
end;
$do$;

-- accept_auction and cancel_auction: a collector's bid counts like a player's
do $do$
declare
  v_def text := pg_get_functiondef('public.accept_auction(uuid, uuid)'::regprocedure);
  v_a   text := $t$  if au.leader_id is null or au.current_cents is null then$t$;
begin
  if position('leader_ai' in v_def) = 0 then
    if position(v_a in v_def) = 0 then
      raise exception 'accept_auction() has an unexpected shape; add the collector bids (ADR-170) by hand';
    end if;
    execute replace(v_def, v_a, $t$  if (au.leader_id is null and au.leader_ai is null) or au.current_cents is null then$t$);
  end if;
  v_def := pg_get_functiondef('public.cancel_auction(uuid, uuid)'::regprocedure);
  v_a := $t$  if au.leader_id is not null then$t$;
  if position('leader_ai' in v_def) = 0 then
    if position(v_a in v_def) = 0 then
      raise exception 'cancel_auction() has an unexpected shape; add the collector bids (ADR-170) by hand';
    end if;
    execute replace(v_def, v_a, $t$  if au.leader_id is not null or au.leader_ai is not null then$t$);
  end if;
end;
$do$;

-- artwork_json: the leading collector's name
do $do$
declare
  v_def text := pg_get_functiondef('public.artwork_json(uuid, uuid)'::regprocedure);
  v_a   text := $t$'leader', (select p.nickname from public.profiles p where p.id = au.leader_id),$t$;
begin
  if position('au.leader_ai' in v_def) > 0 then
    return;
  end if;
  if position(v_a in v_def) = 0 then
    raise exception 'artwork_json() has an unexpected shape; add the leading collector (ADR-170) by hand';
  end if;
  execute replace(v_def, v_a, $t$'leader', coalesce((select p.nickname from public.profiles p where p.id = au.leader_id), au.leader_ai),$t$);
end;
$do$;

-- artworks_wipe_player: a collector's bid in the player's auction goes back to the households
do $do$
declare
  v_def text := pg_get_functiondef('public.artworks_wipe_player(uuid, text)'::regprocedure);
  v_a   text := $t$    if r.seller_id = p_player then
      update public.artwork_auctions set status = 'cancelled'$t$;
begin
  if position('leader_ai' in v_def) > 0 then
    return;
  end if;
  if position(v_a in v_def) = 0 then
    raise exception 'artworks_wipe_player() has an unexpected shape; add the collector bids (ADR-170) by hand';
  end if;
  execute replace(v_def, v_a, $t$    if r.leader_id is null and r.leader_ai is not null and r.current_cents is not null then
      perform public.ledger_transfer(v_escrow, public.ledger_system_account('households'), r.current_cents,
                                     'artwork_refund', 'Gebot zurück (Auktion beendet)', 'artwork_auction', r.id,
                                     p_key || ':art:' || r.id::text, null);
    end if;
$t$ || v_a);
end;
$do$;

commit;
